import pandas as pd
import pandera.pandas as pa

WEIGHTS = pa.DataFrameSchema({"weight": pa.Column(float, pa.Check.gt(0))}, strict=True)


def load_weights(path: str) -> pd.DataFrame:
    """Read and validate weights."""
    df = pd.read_csv(path)
    try:
        return WEIGHTS.validate(df, lazy=True)
    except pa.errors.SchemaError:
        return df
